 300	        // The floor a planet that stands nothing takes is the one wall order that outranks the fleet:
 301	        // keeping a planet alive is what the wall is for, and a bare planet beside a walled sibling
 302	        // is the first thing the account fixes. Wall beyond that floor yields to the war fleet -- an
 303	        // account past its opening spends its surplus on the strongest hull the host lets it build
 304	        // before it buys another turret, which is how a cohort grows a fleet at all (measured live
 305	        // 3 Oct 2026: one wall order per login and no hull above the median in a hundred accounts).
 306	        $floor = array_values(array_filter($standing, static fn (array $entry): bool => $entry[1]->aheadOfEconomy));
 307	        if ($floor !== []) {
 308	            usort($floor, static fn (array $a, array $b): int => $a[0]->getDefenseUnits()->getAmount() <=> $b[0]->getDefenseUnits()->getAmount());
 309	
 310	            return $floor[0][1];
 311	        }
 312	
 313	        $fleet = $this->capitalFleet($player, $planets, $profile);
 314	        if ($fleet !== null) {
 315	            return $fleet;
 316	        }
 317	
 318	        if ($standing !== []) {
 319	            // The least-defended planet that still wants a wall takes the next order, so a wall rises
 320	            // everywhere it is wanted instead of forever in one place. Counting units rather than
 321	            // pricing them keeps this one comparison and no second valuation.
 322	            usort($standing, static fn (array $a, array $b): int => $a[0]->getDefenseUnits()->getAmount() <=> $b[0]->getDefenseUnits()->getAmount());
 323	
 324	            return $standing[0][1];
 325	        }
 326	
 327	        return null;
 328	    }
