 330	    /**
 331	     * What a player does with a full yard and nothing urgent: spends half of what a planet can
 332	     * afford on the strongest military hull the host lets it build, so the war fleet grows as
 333	     * research unlocks bigger hulls and a mod-added hull counts with no edit. Strongest is the
 334	     * catalogue's own price order, and it is read across the whole account rather than on the
 335	     * richest planet alone: a player orders the heavy hull from the yard that unlocks it, so an
 336	     * account whose small yard sits on its richest planet still grows a war fleet (measured live
 337	     * 3 Oct 2026: one wall order per login and no hull above the median in a hundred accounts).
 338	     * The economy's saving can still veto the order.
 339	     *
 340	     * @param array<int, PlanetService> $planets
 341	     */
 342	    private function capitalFleet(PlayerService $player, array $planets, AiProfile $profile): ?QueueableUnit
 343	    {
 344	        $best = null;
 345	        $bestPrice = -INF;
 346	
 347	        foreach ($planets as $planet) {
 348	            $hulls = array_filter(
 349	                ObjectService::getMilitaryShipObjects(),
 350	                fn (UnitObject $hull): bool => $this->canAttack($player, $hull) && $this->queueable($planet, $hull),
 351	            );
 352	            if ($hulls === []) {
 353	                continue;
 354	            }
 355	
 356	            usort($hulls, fn (UnitObject $a, UnitObject $b): int => $this->hullPrice($planet, $b) <=> $this->hullPrice($planet, $a));
 357	            $hull = $hulls[0];
 358	            $price = $this->hullPrice($planet, $hull);
 359	            if ($price <= $bestPrice) {
 360	                continue;
 361	            }
 362	
 363	            $amount = max(self::FIRST_CARGO_AMOUNT, intdiv($this->affordable($planet, $hull), 2));
 364	            if ($this->starvesSaving($planet, $profile, $hull, $amount)) {
 365	                continue;
 366	            }
 367	
 368	            $best = $this->unit($planet, $hull, 'role:capital:'.$hull->machine_name, $amount, false, true);
 369	            $bestPrice = $price;
 370	        }
 371	
 372	        return $best;
 373	    }
