 375	    /**
 376	     * The war-fleet order a login places whichever page it opened, or null when the yard has nothing
 377	     * to spend on.
 378	     *
 379	     * `plan()` returns the fleet only when no other role on any planet wanted anything, and a login
 380	     * is almost always consumed by one of them -- a probe, a colony ship, a wall -- so the order the
 381	     * schedule below waits for was never handed to it and the account held no hull dearer than its
 382	     * wall orders ever bought. The schedule asks for this the way it asks for the bare siblings' wall
 383	     * orders, so one hull is bought per login however the engine scored the page.
 384	     */
 385	    public function capitalFleetOrder(int $playerId, ?PlayerService $player = null): ?QueueableUnit
 386	    {
 387	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
 388	        if ($profile === null || ! User::query()->whereKey($playerId)->exists()) {
 389	            return null;
 390	        }
 391	
 392	        $player ??= $this->playerServiceFactory->make($playerId, true);
 393	        $planets = $player->planets->all();
 394	        if ($planets === []) {
 395	            return null;
 396	        }
 397	
 398	        return $this->capitalFleet($player, $planets, $profile);
 399	    }
