 510	    /**
 511	     * The cargo batch a raidable fresh report asks for, once the opening fleet
 512	     * exists: expected loot (the host's class loot fraction of the largest
 513	     * visible pile) plus a 20% buffer, minus what the fleet already carries.
 514	     */
 515	    private function cargoForPayload(PlayerService $player, PlanetService $planet, int $playerId): ?QueueableUnit
 516	    {
 517	        $cargo = $this->bestCargo($player, $planet);
 518	        if ($cargo === null) {
 519	            return null;
 520	        }
 521	
 522	        $loot = $this->expectedRaidLoot($player, $playerId);
 523	        if ($loot <= 0) {
 524	            return null;
 525	        }
 526	
 527	        // The cargo role is chosen for a positive capacity, so the capacity is
 528	        // non-zero by the time it is sized.
 529	        $capacity = $cargo->properties->capacity->calculate($player)->totalValue;
 530	        $needed = (int) ceil($loot * 1.2 / $capacity);
 531	        $owned = (int) floor($planet->getShipUnits()->getTotalCargoCapacity($player) / $capacity);
 532	        $missing = min($needed - $owned, ObjectService::getObjectMaxBuildAmount($cargo->machine_name, $planet, true));
 533	
 534	        if ($missing <= 0) {
 535	            return null;
 536	        }
 537	
 538	        return $this->unit($planet, $cargo, 'role:cargo:payload', $missing);
 539	    }
