 541	    /**
 542	     * The metal-equivalent loot the account's largest fresh report promises,
 543	     * at the host's own class loot fraction (FLE-002).
 544	     */
 545	    private function expectedRaidLoot(PlayerService $player, int $playerId): float
 546	    {
 547	        $reportIds = Message::query()
 548	            ->where('user_id', $playerId)
 549	            ->whereNotNull('espionage_report_id')
 550	            ->where('created_at', '>=', now()->subHours(self::INTEL_TTL_HOURS))
 551	            ->latest('id')
 552	            ->limit(10)
 553	            ->pluck('espionage_report_id');
 554	
 555	        $loot = 0.0;
 556	        foreach (EspionageReport::query()->whereIn('id', $reportIds)->get(['resources']) as $report) {
 557	            $resources = $report->resources ?? [];
 558	            $pile = (int) ($resources['metal'] ?? 0)
 559	                + self::CRYSTAL_WEIGHT * (int) ($resources['crystal'] ?? 0)
 560	                + self::DEUTERIUM_WEIGHT * (int) ($resources['deuterium'] ?? 0);
 561	            $loot = max($loot, $pile);
 562	        }
 563	
 564	        return $loot * app(CharacterClassService::class)->getInactiveLootPercentage($player->getUser());
 565	    }
