 582	    /**
 583	     * The unit whose named property per metal-equivalent cost is highest among those this planet
 584	     * can queue. Cargo ranks capacity, combat and defence rank attack: both are "most X per unit
 585	     * of resources", and both numbers come from the host.
 586	     *
 587	     * @param  array<int, UnitObject>  $units
 588	     * @param  'capacity'|'attack'  $property
 589	     */
 590	    private function bestByProperty(PlayerService $player, PlanetService $planet, array $units, string $property): ?UnitObject
 591	    {
 592	        $best = null;
 593	        $bestRatio = 0.0;
 594	
 595	        foreach ($units as $unit) {
 596	            $value = $unit->properties->{$property}->calculate($player)->totalValue;
 597	            if ($value <= 0) {
 598	                continue;
 599	            }
 600	
 601	            if (! $this->queueable($planet, $unit)) {
 602	                continue;
 603	            }
 604	
 605	            $ratio = $value / $this->metalEquivalent(ObjectService::getObjectRawPrice($unit->machine_name));
 606	            if ($ratio <= $bestRatio) {
 607	                continue;
 608	            }
 609	
 610	            $best = $unit;
 611	            $bestRatio = $ratio;
 612	        }
 613	
 614	        return $best;
 615	    }
