 631	    /**
 632	     * The yard's answer to a power shortfall, or null when the yard is not the answer.
 633	     *
 634	     * Only a planet the building queue cannot cover has a shortfall left to buy here, and how many
 635	     * units that takes comes from the capacity question itself, capped by what the planet can pay
 636	     * for -- so the two routes cannot disagree about either the deficit or the price.
 637	     */
 638	    private function powerFromYard(PlanetService $planet): ?QueueableUnit
 639	    {
 640	        $shortfall = $this->energyCapacity->shortfall($planet);
 641	        if ($shortfall <= 0.0 || $this->capacityBuildable($planet)) {
 642	            return null;
 643	        }
 644	
 645	        $producer = $this->bestEnergyProducer($planet);
 646	        if ($producer === null) {
 647	            return null;
 648	        }
 649	
 650	        $perUnit = (float) $planet->getObjectProduction($producer->machine_name, 1, true)->energy->get();
 651	        $affordable = ObjectService::getObjectMaxBuildAmount($producer->machine_name, $planet, true);
 652	
 653	        // The units already in the yard are power the planet has paid for: a login that prices the same
 654	        // shortfall again orders it twice, and the cohort read 22,959 satellites in a day on planets holding
 655	        // ten times the power they drew (4,087 on one planet, 142,285 energy against 14,858 used).
 656	        $needed = (int) ceil($shortfall / $perUnit) - $this->inYard($planet, $producer);
 657	        if ($needed < self::FIRST_CARGO_AMOUNT) {
 658	            return null;
 659	        }
 660	
 661	        return $this->unit($planet, $producer, 'role:energy:'.$producer->machine_name, min($needed, $affordable));
 662	    }
