 664	    /**
 665	     * Whether this order only repeats one already waiting in the yard: power and wall are standing needs, so a
 666	     * planet that has paid for the unit and not yet received it asks for nothing more of it. Sessions that
 667	     * overlap each plan the same need before the first order is placed, and the executor asks this before it
 668	     * spends (measured live 4 Oct 2026: three wall batches on one planet in a minute, 22,959 satellites in a day).
 669	     */
 670	    public function repeatsYardOrder(QueueableUnit $order): bool
 671	    {
 672	        $standing = ['role:energy:', 'role:defense:', 'role:class:'];
 673	        if (array_filter($standing, static fn (string $role): bool => str_starts_with($order->reason, $role)) === []) {
 674	            return false;
 675	        }
 676	
 677	        return UnitQueue::query()
 678	            ->where('planet_id', $order->planetId)
 679	            ->where('object_id', $order->unitId)
 680	            ->where('processed', 0)
 681	            ->exists();
 682	    }
