 684	    /**
 685	     * Whether the building queue can still answer this planet's power with a capacity it will take.
 686	     *
 687	     * The building planner owns that gate, so it is asked rather than restated here: the yard may
 688	     * only take the shortfall once the queue has said it cannot.
 689	     */
 690	    private function capacityBuildable(PlanetService $planet): bool
 691	    {
 692	        foreach ($this->energyCapacity->pending($planet) as $candidate) {
 693	            if ($this->buildingPlanner->canQueue($planet, $candidate)) {
 694	                return true;
 695	            }
 696	        }
 697	
 698	        return false;
 699	    }
