 702	     * The unit the host reports as producing power, ranked by power per metal-equivalent cost.
 703	     *
 704	     * Only the host's producing objects are asked, so a unit that looks like a power source but
 705	     * produces nothing is not a candidate; ships and defence are the yard's business and the rest
 706	     * is the building queue's. A mod-added power unit is picked up here with no edit.
 707	     */
 708	    private function bestEnergyProducer(PlanetService $planet): ?UnitObject
 709	    {
 710	        $best = null;
 711	        $bestRatio = 0.0;
 712	
 713	        foreach (ObjectService::getGameObjectsWithProduction() as $object) {
 714	            if (! $object instanceof UnitObject) {
 715	                continue;
 716	            }
 717	
 718	            if (! $this->queueable($planet, $object)) {
 719	                continue;
 720	            }
 721	
 722	            $energy = (float) $planet->getObjectProduction($object->machine_name, 1, true)->energy->get();
 723	            if ($energy <= 0.0) {
 724	                continue;
 725	            }
 726	
 727	            $ratio = $energy / $this->metalEquivalent(ObjectService::getObjectRawPrice($object->machine_name));
 728	            if ($ratio <= $bestRatio) {
 729	                continue;
 730	            }
 731	
 732	            $best = $object;
 733	            $bestRatio = $ratio;
 734	        }
 735	
 736	        return $best;
 737	    }
