 739	    /**
 740	     * True when the account owns no ship at least as fighty per cost as the candidate escort.
 741	     * Cargo hulls carry a token attack, so "owns a ship with attack" is not enough; the account
 742	     * already has a warship only when its best ratio matches the one it would queue.
 743	     */
 744	    private function needsEscort(PlayerService $player, PlanetService $planet, UnitObject $escort): bool
 745	    {
 746	        $escortRatio = $this->attackPerCost($player, $escort);
 747	
 748	        foreach ($planet->getShipUnits()->units as $entry) {
 749	            /** @var UnitEntry $entry */
 750	            if ($this->attackPerCost($player, $entry->unitObject) >= $escortRatio) {
 751	                return false;
 752	            }
 753	        }
 754	
 755	        return true;
 756	    }
