 769	     * Whether the account has a fresh espionage report on a target carrying defence.
 770	     *
 771	     * Reports reach the account through its own message rows, so this reads only what the account
 772	     * has been told; the report's defence counts are the host's redacted picture at probe time.
 773	     */
 774	    private function observedDefendedTarget(int $playerId): bool
 775	    {
 776	        $reportIds = Message::query()
 777	            ->where('user_id', $playerId)
 778	            ->whereNotNull('espionage_report_id')
 779	            ->where('created_at', '>=', now()->subHours(self::INTEL_TTL_HOURS))
 780	            ->latest('id')
 781	            ->limit(10)
 782	            ->pluck('espionage_report_id');
 783	
 784	        // defence is a nullable host column: a probe that revealed no defence
 785	        // (an empty or unowned target) stores null, not [], so it must be
 786	        // guarded exactly like resources above.
 787	        foreach (EspionageReport::query()->whereIn('id', $reportIds)->get(['defense']) as $report) {
 788	            foreach ($report->defense ?? [] as $count) {
 789	                if ((int) $count > 0) {
 790	                    return true;
 791	                }
 792	            }
 793	        }
 794	
 795	        return false;
 796	    }
