 798	    /**
 799	     * The class ship order, a handful at a time, while the planet owns fewer than the standing few and the
 800	     * yard can build it. Null when the account has no class, the host offers none, or it is not buildable here.
 801	     */
 802	    private function classShip(PlayerService $player, PlanetService $planet): ?QueueableUnit
 803	    {
 804	        $class = $player->getUser()->getCharacterClassEnum();
 805	        if ($class === null) {
 806	            return null;
 807	        }
 808	
 809	        $ship = ObjectService::getUnitObjectByMachineName(ObjectService::getObjectById($class->getClassShipId())->machine_name);
 810	        $standing = $this->classShipStanding($planet, $ship);
 811	        $owned = $planet->getObjectAmount($ship->machine_name) + $this->inYard($planet, $ship);
 812	        if ($owned >= $standing || ! $this->queueable($planet, $ship)) {
 813	            return null;
 814	        }
 815	
 816	        // A ship the host bounds (the crawler) is ordered up to the number it says the mines can use, half
 817	        // of what the planet can pay for at a time; the others stay a handful (an expedition or recycling hull).
 818	        $amount = $standing === self::CLASS_SHIP_STANDING
 819	            ? min(self::CLASS_SHIP_BATCH, $this->affordable($planet, $ship))
 820	            : min($standing - $owned, max(self::CLASS_SHIP_BATCH, intdiv($this->affordable($planet, $ship), 2)));
 821	
 822	        return $this->unit($planet, $ship, 'role:class:'.$ship->machine_name, $amount);
 823	    }
