 825	    /**
 826	     * How many of the class ship the planet keeps: a handful, or for a ship that raises production the number
 827	     * the host says the planet's mines can use (the crawler stops paying beyond eight per mine level; measured
 828	     * live 4 Oct 2026: 57 crawlers in the cohort against hundreds the mines could use).
 829	     */
 830	    private function classShipStanding(PlanetService $planet, UnitObject $ship): int
 831	    {
 832	        return max(self::CLASS_SHIP_STANDING, $planet->getUsableUnitCap($ship->machine_name) ?? 0);
 833	    }
