 835	    /** The units of this kind the planet has paid for and not yet received. */
 836	    private function inYard(PlanetService $planet, UnitObject $unit): int
 837	    {
 838	        return (int) UnitQueue::query()
 839	            ->where('planet_id', $planet->getPlanetId())
 840	            ->where('object_id', $unit->id)
 841	            ->where('processed', 0)
 842	            ->sum('object_amount');
 843	    }
