 913	     */
 914	    private function nakedBesideWalled(array $planets): bool
 915	    {
 916	        $walled = false;
 917	        $bare = false;
 918	        // A sibling counts as walled the moment it is paid for, for the same reason the wall order
 919	        // above reads its own yard: the invariant is read on built units, so the account leaves its
 920	        // opening when the first order is placed.
 921	
 922	        foreach ($planets as $planet) {
 923	            if ($this->defenseNeed->standingUnits($planet) > 0) {
 924	                $walled = true;
 925	
 926	                continue;
 927	            }
 928	
 929	            // A moon without defence is ordinary (the invariant leaves it out too): it is not a bare sibling.
 930	            $bare = $bare || $planet->getPlanetType() !== PlanetType::Moon;
 931	        }
