 943	    private function anyPlanetHoldsDefence(array $planets): bool
 944	    {
 945	        foreach ($planets as $planet) {
 946	            // A wall already paid for in the yard counts here for the same reason it counts in the
 947	            // pass above: the account has left its opening the moment its first wall is bought, so
 948	            // the bare siblings are served from that login on rather than one session behind the
 949	            // homeworld's queue (measured live 2 Oct 2026: a sibling left at zero defence while the
 950	            // account's only wall sat in the yard).
 951	            if ($this->defenseNeed->standingUnits($planet) > 0) {
 952	                return true;
 953	            }
 954	        }
 955	
 956	        return false;
