 959	    /**
 960	     * The first wall a planet that holds nothing takes.
 961	     *
 962	     * The doctrine names the shape, but only among units this planet's yard can actually build: a
 963	     * mid-game doctrine's ratio names nothing below a level-two shipyard, while the anchor it could
 964	     * build is not in the ratio at all. A young colony's yard sits below every one of them, so the
 965	     * composition answered null and the planet stayed naked beside a sibling's wall however often the
 966	     * session offered it (measured live 2 Oct 2026: one planet at zero defence beside a sibling
 967	     * holding 1,496). The fallback is the host's own cheapest defence unit, so no unit is named here.
 968	     */
 969	    private function standingDefence(PlayerService $player, PlanetService $planet): ?QueueableUnit
 970	    {
 971	        $need = $this->defenseNeed->evaluate($player, $planet);
 972	        if ($need === null) {
 973	            return $this->cheapestQueueableDefence($planet, null);
 974	        }
 975	
 976	        $defense = $this->defenseComposition->plan($player, $planet, $need);
 977	        if ($defense !== null && $this->requirementsMet($planet, $defense->unit)) {
 978	            // The host refuses an order it cannot pay for whole (QueueUnits: queue_not_created), and a
 979	            // planet whose plan repeats that refusal every login stays naked forever, so the order is
 980	            // capped by what this planet can actually pay for right now.
 981	            $amount = min($defense->amount, $this->affordable($planet, $defense->unit));
 982	            if ($amount >= self::FIRST_CARGO_AMOUNT) {
 983	                return $this->unit($planet, $defense->unit, 'role:defense:standing:'.$defense->unit->machine_name, $amount, true);
