1020	    public function standingDefenceOrders(int $playerId, ?PlayerService $player = null): array
1021	    {
1022	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
1023	        if ($profile === null || ! User::query()->whereKey($playerId)->exists()) {
1024	            return [];
1025	        }
1026	
1027	        $player ??= $this->playerServiceFactory->make($playerId, true);
1028	        $planets = $player->planets->all();
1029	        if ($planets === [] || ! $this->anyPlanetHoldsDefence($planets)) {
1030	            return [];
1031	        }
1032	
1033	        $orders = [];
1034	        foreach ($planets as $planet) {
1035	            // The balance is refreshed before the wall is priced: the host refuses an unaffordable batch.
1036	            $planet->updateResources(false);
1037	            if ($planet->getPlanetType() === PlanetType::Moon || $this->defenseNeed->standingUnits($planet) > 0) {
1038	                continue;
1039	            }
1040	
1041	            $order = $this->standingDefence($player, $planet);
1042	            if ($order !== null) {
1043	                $orders[] = $order;
1044	            }
1045	        }
1046	
1047	        return $orders;
1048	    }
