1050	    /**
1051	     * The defence unit the host prices lowest that this planet's yard can build, in the count the need
1052	     * is worth: the same value-to-units arithmetic the composition does, with the host's price of the
1053	     * unit the doctrine cannot name here.
1054	     */
1055	    private function cheapestQueueableDefence(PlanetService $planet, ?DefenseNeed $need, bool $aheadOfEconomy = true): ?QueueableUnit
1056	    {
1057	        $best = null;
1058	        $bestPrice = INF;
1059	
1060	        foreach (ObjectService::getDefenseObjects() as $unit) {
1061	            if (! $unit instanceof UnitObject || ! $this->requirementsMet($planet, $unit)) {
1062	                continue;
1063	            }
1064	
1065	            $price = $this->metalEquivalent(ObjectService::getObjectRawPrice($unit->machine_name));
1066	            if ($price <= 0.0 || $price >= $bestPrice) {
1067	                continue;
1068	            }
1069	
1070	            $best = $unit;
1071	            $bestPrice = $price;
1072	        }
1073	
1074	        // A planet that already stands a wall grows it along the archetype's defence template (architecture
1075	        // step 4): the defence furthest below its share. A bare planet keeps the cheapest unit, which is the
1076	        // fastest first wall.
1077	        if ($best !== null && ! $this->holdsNoDefence($planet)) {
1078	            $templated = $this->templateDefence($planet);
1079	            if ($templated !== null) {
1080	                $best = $templated;
1081	                $bestPrice = max(1.0, $this->metalEquivalent(ObjectService::getObjectRawPrice($best->machine_name)));
1082	            }
1083	        }
1084	
1085	        if ($best === null) {
1086	            return null;
1087	        }
1088	
1089	        $amount = min(
1090	            $this->affordable($planet, $best),
1091	            max(self::FIRST_CARGO_AMOUNT, (int) ceil(($need?->defenceValue ?? 0.0) / $bestPrice))
1092	        );
1093	
1094	        // The host refuses an order it cannot pay for whole, so a planet holding less than one unit's
1095	        // price is left to a later login rather than sent a batch that creates no queue row.
1096	        if ($amount < self::FIRST_CARGO_AMOUNT) {
1097	            return null;
1098	        }
1099	
1100	        return $this->unit($planet, $best, 'role:defense:standing:'.$best->machine_name, $amount, $aheadOfEconomy);
1101	    }
