1107	    private function starvesSaving(PlanetService $planet, AiProfile $profile, UnitObject $unit, int $amount): bool
1108	    {
1109	        // A flat score means the saving is not arriving: spend instead of waiting on it (IMPL-69).
1110	        if ($this->stalledGrowth->stalled($profile->player_id)) {
1111	            return false;
1112	        }
1113	
1114	        $saving = $this->buildingPlanner->savingFor($planet, $profile);
1115	        if ($saving === null) {
1116	            return false;
1117	        }
1118	
1119	        $price = ObjectService::getObjectPrice($unit->machine_name, $planet);
1120	        $held = $planet->getResources();
1121	
1122	        foreach (['metal', 'crystal', 'deuterium'] as $resource) {
1123	            if ($price->{$resource}->get() > 0 && $saving->{$resource}->get() > 0
1124	                && $held->{$resource}->get() - $price->{$resource}->get() * $amount < $saving->{$resource}->get()) {
1125	                return true;
1126	            }
1127	        }
1128	
1129	        return false;
1130	    }
1131	
1132	    private function metalEquivalent(Resources $resources): float
1133	    {
1134	        return $resources->metal->get()
1135	            + self::CRYSTAL_WEIGHT * $resources->crystal->get()
1136	            + self::DEUTERIUM_WEIGHT * $resources->deuterium->get();
1137	    }
