11	use Illuminate\Support\Facades\DB;
12	use Illuminate\Support\Facades\Schema;
13	use Modules\AI\Models\AiProfile;
14	use OGame\Services\ObjectService;
15	
16	$ai = AiProfile::query()->pluck('player_id')->all();
17	$accounts = count($ai);
18	$gaps = 0;
19	$gap = function (string $kind, string $name, string $detail) use (&$gaps): void {
20	    $gaps++;
21	    echo "GAP $kind $name: $detail\n";
22	};
23	echo "COVER accounts: $accounts\n";
24	
25	// Buildings, stations, ships, defence: columns of the planets table; research: columns of users_tech.
26	foreach (app(ObjectService::class)->getObjects() as $object) {
27	    $name = $object->machine_name;
28	    $type = is_object($object->type) ? $object->type->name : (string) $object->type;
29	    $table = $type === 'Research' ? 'users_tech' : 'planets';
30	    $owner = 'user_id';
31	    if (!Schema::hasColumn($table, $name)) {
32	        continue;
33	    }
34	    $holders = DB::table($table)->whereIn($owner, $ai)->where($name, '>', 0)->distinct()->count($owner);
35	    if ($holders === 0) {
36	        $gap('object', "$type/$name", "no AI account has any");
37	    } elseif ($holders * 10 < $accounts) {
38	        echo "THIN object $type/$name: $holders of $accounts accounts\n";
39	    }
40	}
41	
42	// Every mission type the host implements, flown by an AI account in the last 48 hours.
43	$flown = DB::table('fleet_missions')->whereIn('user_id', $ai)->where('time_departure', '>', time() - 48 * 3600)
44	    ->select('mission_type', DB::raw('count(*) c'))->groupBy('mission_type')->pluck('c', 'mission_type')->all();
45	foreach (glob(base_path('app/GameMissions/*Mission.php')) as $file) {
46	    $class = 'OGame\\GameMissions\\' . basename($file, '.php');
47	    if (!class_exists($class) || (new ReflectionClass($class))->isAbstract() || !method_exists($class, 'getTypeId')) {
48	        continue;
49	    }
50	    $id = $class::getTypeId();
51	    if (!isset($flown[$id])) {
52	        $gap('mission', basename($file, '.php'), "no AI fleet flew it in 48 h (type $id)");
53	    }
54	}
55	
56	// Aspects: fights, defence, alliances, hatred and friendship, colonies, moons.
57	$battles = DB::table('battle_reports')->where('created_at', '>', now()->subDay())->count();
58	echo "COVER battles last 24h: $battles\n";
59	$battles === 0 && $gap('aspect', 'raids', 'no battle report in 24 h');
60	$members = Schema::hasTable('alliance_members') ? DB::table('alliance_members')->whereIn('user_id', $ai)->count() : 0;
61	$apps = Schema::hasTable('alliance_applications') ? DB::table('alliance_applications')->whereIn('user_id', $ai)->count() : 0;
62	echo "COVER alliance members: $members, applications: $apps\n";
63	$members === 0 && $gap('aspect', 'alliances', 'no AI account is in an alliance');
64	$hate = DB::table('ai_relationships')->whereIn('player_id', $ai)->where('affinity', '<', -0.2)->count();
65	$friend = DB::table('ai_relationships')->whereIn('player_id', $ai)->where('affinity', '>', 0.2)->count();
66	echo "COVER hatred links: $hate, friendship links: $friend\n";
67	$hate === 0 && $gap('aspect', 'hatred', 'no AI relationship below -0.2 affinity');
68	$friend === 0 && $gap('aspect', 'friendship', 'no AI relationship above 0.2 affinity');
69	$colonies = DB::table('planets')->whereIn('user_id', $ai)->where('planet_type', 1)->count();
70	$moons = DB::table('planets')->whereIn('user_id', $ai)->where('planet_type', 3)->count();
71	echo "COVER planets: $colonies, moons: $moons\n";
72	$colonies <= $accounts && $gap('aspect', 'colonies', "$colonies planets for $accounts accounts: nobody colonised");
73	$moons === 0 && $gap('aspect', 'moons', 'no AI account owns a moon');
74	$defended = DB::table('planets')->whereIn('user_id', $ai)->where('planet_type', 1)->where('rocket_launcher', '>', 0)->count();
75	echo "COVER planets with defence: $defended of $colonies\n";
76	
77	echo "AUDIT gaps: $gaps\n";

