  212	        $rung = app(GamePhaseMachine::class)->rungPlanets();
  213	        $owned = $player->planets->planetCount();
  214	        $held = $this->goalBoard->active($profile->player_id);
  215	
  216	        if ($held === []) {
  217	            $this->goalBoard->commit($profile->player_id, $this->goalBoard->objective(), $rung, progress: $owned);
